"""N=16 3-seed SCS analysis: Spearman rho, AUROC, ranking consistency."""
import json, sys
import numpy as np
from collections import Counter
from scipy.stats import spearmanr

sys.path.insert(0, '/root/autodl-tmp/struct_self_consist_ie/code')
from consistency import structural_consistency_soft_jaccard, fleiss_kappa_surface
from evaluation import per_instance_f1, compute_auroc

SEEDS = [42, 123, 456]
BASE = "/root/autodl-tmp/struct_self_consist_ie/output"
PATHS = {
    42: f"{BASE}/exp001_n16_seed42/samples.jsonl",
    123: f"{BASE}/exp001_n16_seed123/samples.jsonl",
    456: f"{BASE}/exp001_n16_seed456/samples.jsonl",
}
SIGNAL_NAMES = ["SJ", "FK", "VC", "EM", "LP"]

def load_data(path):
    records = []
    with open(path) as f:
        for line in f:
            if line.strip():
                records.append(json.loads(line))
    return records

def compute_exact_match_rate(samples, subtask):
    if subtask == "ner":
        keys = [frozenset((e["text"], e["type"]) for e in s.get("entities", [])) for s in samples]
    else:
        keys = [frozenset((r["head"], r["tail"], r["type"]) for r in s.get("relations", [])) for s in samples]
    if not keys:
        return 0.0
    counter = Counter(keys)
    return counter.most_common(1)[0][1] / len(samples)

def compute_voting_confidence(samples, subtask):
    N = len(samples)
    if N == 0:
        return 0.0
    counter = Counter()
    if subtask == "ner":
        for s in samples:
            for e in s.get("entities", []):
                counter[(e["text"], e["type"])] += 1
    else:
        for s in samples:
            for r in s.get("relations", []):
                counter[(r["head"], r["tail"], r["type"])] += 1
    if not counter:
        return 0.0
    rates = [v / N for v in counter.values()]
    return float(np.mean(rates))

def compute_mean_logprob(samples):
    logprobs = [s.get("mean_logprob") for s in samples if s.get("mean_logprob") is not None]
    logprobs = [lp for lp in logprobs if np.isfinite(lp)]
    if not logprobs:
        return float("nan")
    return float(np.mean(logprobs))

def analyze_seed(seed, subtask):
    records = load_data(PATHS[seed])
    if subtask == "ner":
        valid = [r for r in records if len(r["gold"].get("entities", [])) > 0]
    else:
        valid = [r for r in records if len(r["gold"].get("relations", [])) > 0]

    sj_vals, fk_vals, vc_vals, em_vals, lp_vals, f1_vals = [], [], [], [], [], []
    for i, inst in enumerate(valid):
        samples = inst["samples"]
        gold = inst["gold"]
        greedy = inst.get("greedy", samples[0])
        sj_vals.append(structural_consistency_soft_jaccard(samples, subtask=subtask))
        fk_vals.append(fleiss_kappa_surface(samples, subtask=subtask))
        vc_vals.append(compute_voting_confidence(samples, subtask))
        em_vals.append(compute_exact_match_rate(samples, subtask))
        lp_vals.append(compute_mean_logprob(samples))
        f1_vals.append(per_instance_f1(greedy, gold, subtask=subtask))
        if (i+1) % 100 == 0:
            print(f"  [{subtask}] {i+1}/{len(valid)} instances processed", flush=True)

    signals = {"SJ": sj_vals, "FK": fk_vals, "VC": vc_vals, "EM": em_vals, "LP": lp_vals}
    rho_results, auroc_results = {}, {}
    for name in SIGNAL_NAMES:
        vals = np.array(signals[name])
        f1_arr = np.array(f1_vals)
        mask = np.isfinite(vals) & np.isfinite(f1_arr)
        v, f = vals[mask], f1_arr[mask]
        rho_results[name] = round(float(spearmanr(v, f).statistic), 4)
        auroc_results[name] = round(float(compute_auroc(v.tolist(), f.tolist())), 4)
    return {"n_valid": len(valid), "rho": rho_results, "auroc": auroc_results}

results = {}
for seed in SEEDS:
    results[seed] = {}
    for subtask in ["ner", "re"]:
        print(f"=== seed={seed}, {subtask} ===", flush=True)
        results[seed][subtask] = analyze_seed(seed, subtask)
        print(f"  n={results[seed][subtask]['n_valid']}, rho={results[seed][subtask]['rho']}", flush=True)

out_path = f"{BASE}/n16_3seed_5signal_results.json"
with open(out_path, "w") as f:
    json.dump(results, f, indent=2)
print(f"\nSaved to {out_path}")
print("RESULTS_JSON_START")
print(json.dumps(results, indent=2))
print("RESULTS_JSON_END")
